class Solution {
public:
    int maxMoves(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<bool> reachable(m, true);
        for (int c = 0; c < n - 1; c++) {
            std::vector<bool> nxt(m, false);
            bool any_reach = false;
            for (int r = 0; r < m; r++) {
                if (!reachable[r]) continue;
                for (int dr = -1; dr <= 1; dr++) {
                    int nr = r + dr;
                    if (nr >= 0 && nr < m && grid[nr][c + 1] > grid[r][c]) {
                        nxt[nr] = true;
                        any_reach = true;
                    }
                }
            }
            if (!any_reach) return c;
            reachable = std::move(nxt);
        }
        return n - 1;
    }
};

class Solution {
    public int maxMoves(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[] reachable = new boolean[m];
        Arrays.fill(reachable, true);
        for (int c = 0; c < n - 1; c++) {
            boolean[] nxt = new boolean[m];
            boolean anyReach = false;
            for (int r = 0; r < m; r++) {
                if (!reachable[r]) continue;
                for (int dr = -1; dr <= 1; dr++) {
                    int nr = r + dr;
